package com.tnc.tnc.life.routes.mech;
import com.tnc.tnc.life.routes.*;
import com.tnc.tnc.adventure.AdventureGameTests;
import net.minecraft.gametest.framework.*;
import net.minecraftforge.gametest.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.item.*;
import net.minecraft.world.InteractionHand;
import net.minecraft.core.BlockPos;
@GameTestHolder("tncroute") @PrefixGameTestTemplate(false)
public final class MechGameTests {
    private static ItemStack equip(net.minecraft.server.level.ServerPlayer p,int amount){var stack=new ItemStack(RouteContent.item("mana_mech"));p.setItemSlot(EquipmentSlot.CHEST,stack);RouteChargeLedger.get(p.serverLevel()).deposit(stack,MechRules.CAPACITY,amount);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(RouteContent.item("mech_spellgun")));p.startUsingItem(InteractionHand.MAIN_HAND);return stack;}
    @GameTest(template="mirror_test_empty",timeoutTicks=60) public static void suitAndRealChargeAreRequired(GameTestHelper h){var p=AdventureGameTests.player(h);h.assertTrue(!MechCombat.fire(p)&&!MechCombat.activate(p,MechNetwork.Action.DASH),"unworn suit cannot fire or dash");var stack=equip(p,0);h.assertTrue(!MechCombat.fire(p)&&!MechCombat.activate(p,MechNetwork.Action.SHIELD),"empty reactor cannot create shots or shields");h.assertTrue(RouteChargeLedger.get(h.getLevel()).amount(stack)==0,"failed actions cannot mint charge");h.succeed();}
    @GameTest(template="mirror_test_empty",timeoutTicks=60) public static void elementalGunUsesChargeNotArrowsAndHonorsCadence(GameTestHelper h){var p=AdventureGameTests.player(h);var stack=equip(p,1000);var at=h.absolutePos(new BlockPos(3,2,3));p.setPos(at.getX()+.5,at.getY(),at.getZ()+.5);p.setYRot(0);p.setXRot(0);var target=net.minecraft.world.entity.EntityType.ZOMBIE.create(h.getLevel());target.setPos(at.getX()+.5,at.getY(),at.getZ()+5.5);target.setNoAi(true);h.getLevel().addFreshEntity(target);h.assertTrue(MechCombat.fire(p),"charged suit fires without arrows");var ledger=RouteChargeLedger.get(h.getLevel());h.assertTrue(ledger.amount(stack)==988,"one shot spends exactly twelve");h.assertTrue(target.getHealth()<target.getMaxHealth(),"elemental shot deals real damage");MechCombat.fire(p);h.assertTrue(ledger.amount(stack)==988,"same-tick repeat cannot bypass fire period");target.discard();h.succeed();}
    @GameTest(template="mirror_test_empty",timeoutTicks=60) public static void barrierConsumesChargeForDamageAndCooldownCannotBeSpamBypassed(GameTestHelper h){var p=AdventureGameTests.player(h);var stack=equip(p,2000);h.assertTrue(MechCombat.activate(p,MechNetwork.Action.SHIELD),"shield starts");h.assertTrue(!MechCombat.activate(p,MechNetwork.Action.SHIELD),"same shield cooldown rejects repeat");var hit=new net.minecraftforge.event.entity.living.LivingHurtEvent(p,h.getLevel().damageSources().generic(),10);MechCombat.hurt(hit);h.assertTrue(Math.abs(hit.getAmount()-2)<.01,"barrier absorbs eighty percent");h.assertTrue(RouteChargeLedger.get(h.getLevel()).amount(stack)==1520,"200 activation plus 280 real absorbed-damage cost");h.succeed();}
    @GameTest(template="mirror_test_empty",timeoutTicks=60) public static void overheatingStopsFireWithoutSpendingExtraMana(GameTestHelper h){var p=AdventureGameTests.player(h);var stack=equip(p,1000);stack.getOrCreateTag().putInt("MechHeat",999);MechCombat.fire(p);var ledger=RouteChargeLedger.get(h.getLevel());h.assertTrue(stack.getTag().getLong("MechVent")>MechCombat.now(p),"overheated reactor vents");int remaining=ledger.amount(stack);h.assertTrue(!MechCombat.fire(p)&&ledger.amount(stack)==remaining,"venting cannot fire or debit repeated failed shots");h.succeed();}
    @GameTest(template="mirror_test_empty",timeoutTicks=60) public static void legacySuitCapacityUpgradePreservesBalanceAndCloneIdentity(GameTestHelper h){var old=new ItemStack(RouteContent.item("mana_mech"));var ledger=RouteChargeLedger.get(h.getLevel());ledger.deposit(old,6000,6000);var copy=old.copy();h.assertTrue(ledger.deposit(old,MechRules.CAPACITY,6000)==6000&&ledger.amount(copy)==12000,"capacity expands only with actual supplied mana");ledger.spend(copy,120);h.assertTrue(ledger.amount(old)==11880,"copied identities still share one balance");h.succeed();}
    @GameTest(template="mirror_test_empty",timeoutTicks=60) public static void novaDoesNotDestroyBlocksOrDamageFarmAnimals(GameTestHelper h){var p=AdventureGameTests.player(h);equip(p,2000);var at=h.absolutePos(new BlockPos(4,2,4));p.setPos(at.getX()+.5,at.getY(),at.getZ()+.5);var cow=net.minecraft.world.entity.EntityType.COW.create(h.getLevel());cow.setPos(at.getX()+2,at.getY(),at.getZ());h.getLevel().addFreshEntity(cow);var stone=at.offset(0,0,2);h.getLevel().setBlock(stone,net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),3);h.assertTrue(MechCombat.activate(p,MechNetwork.Action.NOVA),"nova starts");h.assertTrue(cow.getHealth()==cow.getMaxHealth()&&h.getLevel().getBlockState(stone).is(net.minecraft.world.level.block.Blocks.STONE),"nova preserves farm animals and terrain");cow.discard();h.succeed();}
    @GameTest(template="mirror_test_empty",timeoutTicks=60) public static void shieldUsesLastNineManaWithoutFloatOvercharge(GameTestHelper h){var p=AdventureGameTests.player(h);var stack=equip(p,209);MechCombat.activate(p,MechNetwork.Action.SHIELD);var hit=new net.minecraftforge.event.entity.living.LivingHurtEvent(p,h.getLevel().damageSources().generic(),10);MechCombat.hurt(hit);h.assertTrue(hit.getAmount()<10&&Math.abs(hit.getAmount()-(10-9/35f))<.0001,"partial shield absorbs affordable damage");h.assertTrue(RouteChargeLedger.get(h.getLevel()).amount(stack)==0,"last nine mana spent exactly once");h.succeed();}
}
